children.onClick:
try {
  if ((cards.YD || []).length === 0) {
    functions.chatLog('Y Deck is empty');
  } else {
    await functions.drawFromExtraDeck('YD', 1, false, 'Hand');
  }
} catch (e) {
  functions.chatLog('[DeckSetup] draw ERROR: ' + (e && e.message ? e.message : e));
}

try {
  if ((cards.YE || []).length === 0) {
    functions.chatLog('Extra Deck is empty');
  } else {
    await functions.drawFromExtraDeck('YE', 1, false, 'Hand');
  }
} catch (e) {
  functions.chatLog('[DeckSetup] draw ERROR: ' + (e && e.message ? e.message : e));
}

try {
  functions.chatLog('[DeckSetup] button fired');
  const MAP = { YD: 'YD', YE: 'YE' };
  const dests = Object.values(MAP);
  const groups = {};
  const types = {};
  let total = 0;
  for (const sec of ['Deck', 'Sideboard']) {
    if (dests.includes(sec)) continue;
    for (const c of (cards[sec] || [])) {
      const d = functions.getCardData(c);
      const t = d?.type || d?.face?.front?.type;
      types[t] = (types[t] || 0) + 1;
      const dest = MAP[t];
      if (!dest) continue;
      if (!groups[dest]) groups[dest] = [];
      groups[dest].push(c);
      total++;
    }
  }
  for (const dest of Object.keys(groups)) {
    await functions.moveCards(groups[dest], dest, { noLogs: true });
  }
  if (groups.YD) await functions.shuffleSection('YD');
  if (total > 0) await functions.repositionCards();
  functions.chatLog('[DeckSetup] moved ' + total + ' | sections: ' + Object.keys(cards).map(k => k + '=' + (cards[k] || []).length).join(', ') + ' | types: ' + Object.keys(types).map(k => k + '=' + types[k]).join(', '));
} catch (e) {
  functions.chatLog('[DeckSetup] ERROR: ' + (e && e.message ? e.message : e));
}

